query snapshot_registry {
 require $iteration ITERATION_SNAPSHOT $copy;
 require $copy COLLECTION_SNAPSHOT_OF $listeners;
 require $iteration ITERATION_INVOKES_VALUE $invocation;
 require $notify HAS_CALL $invocation;
 require $unit HAS_METHOD $notify;
 require $unit HAS_FIELD $listeners;
 require $insertion INSERTS_INTO $listeners;
 require $insertion INSERTED_VALUE $listener;
 require $subscribe HAS_CALL $insertion;
 require $subscribe HAS_PARAMETER $listener;
 parameter(receiver: false) as $listener;
 any { require $unit HAS_METHOD $subscribe; }
 or {
   require $subscribe OWNED_BY $registration;
   require $unit HAS_METHOD $registration;
   require $registration HAS_CALL $setup;
   require $setup ARGUMENT $callback;
   require $callback VALUE $subscribe;
   different $registration $notify;
 }
 different $subscribe $notify;
 emit $unit, $listeners, $insertion, $subscribe, $notify, $iteration, $copy, $invocation;
}
